/// The gallery's example of `Collapse`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        let open = State::new(args.bool("open"));
        let flip = open.clone();
        view_fn(move || {
            let toggle = flip.clone();
            VStack::new((
                Button::new("Toggle")
                    .style(ButtonStyle::Secondary)
                    .on_click(move || toggle.update(|o| *o = !*o)),
                {
                    let mut it =
                        Collapse::new(open.get(), Text::new("The height animates, whatever the content."));
                    it
                },
            ))
            .spacing(12.0)
        })
    })
}

impl ComponentBook for Collapse {
    fn book() -> Meta {
        Meta::new("Layout/Collapse", render)
            .summary("Animates its content's height as it opens and closes.")
            .arg(ArgType::bool("open", true).description("How the example starts."))
            .story("Example", Args::new())
    }
}
